<script>
    // State management for interactive calculator
    let activeBankRate = 3.50;

    function formatIDR(amount) {
      return new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(amount).replace('Rp', 'IDR');
    }

    function calculateKPR() {
      const priceSlider = document.getElementById('price-slider');
      const dpSlider = document.getElementById('dp-slider');
      const tenorSlider = document.getElementById('tenor-slider');

      if (!priceSlider || !dpSlider || !tenorSlider) return;

      const price = parseFloat(priceSlider.value);
      const dpPercent = parseFloat(dpSlider.value);
      const tenorYears = parseFloat(tenorSlider.value);

      const dpAmount = price * (dpPercent / 100);
      const loanAmount = price - dpAmount;

      document.getElementById('price-display').innerText = formatIDR(price);
      document.getElementById('dp-percent-display').innerText = dpPercent + '%';
      document.getElementById('dp-amount-display').innerText = formatIDR(dpAmount);
      document.getElementById('tenor-display').innerText = tenorYears + ' Years (' + (tenorYears * 12) + ' Mos)';
      document.getElementById('loan-amount-display').innerText = formatIDR(loanAmount);

      // Monthly payment formula: M = P * [r(1+r)^n] / [(1+r)^n - 1]
      const monthlyRate = (activeBankRate / 100) / 12;
      const totalMonths = tenorYears * 12;
      const monthlyInstallment = loanAmount * (monthlyRate * Math.pow(1 + monthlyRate, totalMonths)) / (Math.pow(1 + monthlyRate, totalMonths) - 1);

      document.getElementById('monthly-installment-display').innerText = formatIDR(monthlyInstallment);
      
      // Minimum income rule (installment should be max 40% of household income)
      const minIncome = monthlyInstallment / 0.4;
      document.getElementById('income-display').innerText = '~' + formatIDR(minIncome) + ' / mo';

      // Update proportion bar
      const principalRatio = Math.max(20, Math.min(80, 100 - (activeBankRate * 7)));
      const interestRatio = 100 - principalRatio;
      document.getElementById('chart-principal').style.width = principalRatio + '%';
      document.getElementById('chart-interest').style.width = interestRatio + '%';
    }

    function setBankRate(rate, bankName, buttonEl) {
      activeBankRate = rate;
      document.getElementById('rate-display').innerText = rate.toFixed(2) + '% p.a. (' + bankName + ')';
      
      const pills = document.querySelectorAll('.bank-pill');
      pills.forEach(pill => {
        pill.classList.remove('bg-property-minimalist-primary', 'text-property-minimalist-on-primary');
        pill.classList.add('bg-property-minimalist-surface-container', 'text-property-minimalist-primary');
      });

      if (buttonEl) {
        buttonEl.classList.remove('bg-property-minimalist-surface-container', 'text-property-minimalist-primary');
        buttonEl.classList.add('bg-property-minimalist-primary', 'text-property-minimalist-on-primary');
      }

      calculateKPR();
    }

    function requestKPRConsult() {
      const price = document.getElementById('price-slider').value;
      const dp = document.getElementById('dp-slider').value;
      const tenor = document.getElementById('tenor-slider').value;
      const text = encodeURIComponent(`Halo Tim KPR Denim Horizon, saya ingin konsultasi simulasi KPR:\n- Harga Properti: IDR ${price}\n- DP: ${dp}%\n- Tenor: ${tenor} Tahun\n- Suku Bunga: ${activeBankRate}% p.a.`);
      window.open(`https://wa.me/6281277004674?text=${text}`, '_blank');
    }

    // Perspective render toggle (day vs night)
    function setRenderPerspective(mode) {
      const dayEl = document.getElementById('render-day');
      const nightEl = document.getElementById('render-night');
      const btnDay = document.getElementById('toggle-day');
      const btnNight = document.getElementById('toggle-night');

      if (mode === 'day') {
        dayEl.classList.remove('opacity-0', 'pointer-events-none');
        dayEl.classList.add('opacity-100');
        nightEl.classList.remove('opacity-100');
        nightEl.classList.add('opacity-0', 'pointer-events-none');

        btnDay.classList.add('bg-property-minimalist-primary', 'text-property-minimalist-on-primary');
        btnDay.classList.remove('text-property-minimalist-on-surface-variant');
        btnNight.classList.remove('bg-property-minimalist-primary', 'text-property-minimalist-on-primary');
        btnNight.classList.add('text-property-minimalist-on-surface-variant');
      } else {
        nightEl.classList.remove('opacity-0', 'pointer-events-none');
        nightEl.classList.add('opacity-100');
        dayEl.classList.remove('opacity-100');
        dayEl.classList.add('opacity-0', 'pointer-events-none');

        btnNight.classList.add('bg-property-minimalist-primary', 'text-property-minimalist-on-primary');
        btnNight.classList.remove('text-property-minimalist-on-surface-variant');
        btnDay.classList.remove('bg-property-minimalist-primary', 'text-property-minimalist-on-primary');
        btnDay.classList.add('text-property-minimalist-on-surface-variant');
      }
    }

    // Filter units
    function filterUnits(type, buttonEl) {
      const cards = document.querySelectorAll('.unit-card');
      const buttons = document.querySelectorAll('.filter-btn');

      buttons.forEach(btn => {
        btn.classList.remove('bg-property-minimalist-primary', 'text-property-minimalist-on-primary');
        btn.classList.add('text-property-minimalist-on-surface-variant');
      });

      if (buttonEl) {
        buttonEl.classList.remove('text-property-minimalist-on-surface-variant');
        buttonEl.classList.add('bg-property-minimalist-primary', 'text-property-minimalist-on-primary');
      }

      cards.forEach(card => {
        if (type === 'all' || card.getAttribute('data-type') === type) {
          card.style.display = 'flex';
        } else {
          card.style.display = 'none';
        }
      });
    }

    // Modal interactions
    function openModal(name, specs, details, price) {
      document.getElementById('modal-unit-name').innerText = name;
      document.getElementById('modal-specs').innerText = specs + ' &bull; ' + details;
      document.getElementById('modal-price').innerText = price;
      document.getElementById('modal-wa-btn').href = `https://wa.me/6281277004674?text=Halo%20Denim%20Horizon,%20saya%20tertarik%20melihat%20detail%20unit%20${encodeURIComponent(name)}`;
      
      const modal = document.getElementById('blueprint-modal');
      modal.classList.remove('hidden');
      modal.classList.add('flex');
    }

    function closeModal() {
      const modal = document.getElementById('blueprint-modal');
      modal.classList.add('hidden');
      modal.classList.remove('flex');
    }

    function downloadTechnicalSheet() {
      alert('Architectural PDF Brochure & Cadastral Floor Plan will be downloaded shortly.');
    }

    // Reservation handler
    function handleReservationSubmit(e) {
      e.preventDefault();
      document.getElementById('reservation-form').classList.add('opacity-50', 'pointer-events-none');
      document.getElementById('reservation-success').classList.remove('hidden');
    }

    // Accordion FAQ toggle
    function toggleFaq(btn) {
      const item = btn.parentElement;
      const answer = item.querySelector('.faq-answer');
      const icon = item.querySelector('.faq-icon');

      if (answer.style.maxHeight && answer.style.maxHeight !== '0px') {
        answer.style.maxHeight = '0px';
        icon.style.transform = 'rotate(0deg)';
      } else {
        // Close others
        document.querySelectorAll('.faq-answer').forEach(el => el.style.maxHeight = '0px');
        document.querySelectorAll('.faq-icon').forEach(el => el.style.transform = 'rotate(0deg)');

        answer.style.maxHeight = answer.scrollHeight + 'px';
        icon.style.transform = 'rotate(180deg)';
      }
    }

    // Initialize calculator on render
    document.addEventListener('DOMContentLoaded', () => {
      calculateKPR();
    });
  </script>
